styles.css:
/* Prism DuckDuckGo module */
html.prism-mod-duckduckgo { --prism-radius: calc(var(--prism-cornerRadius, 10px)); }

/* ===== Theme modes (CSS-only presets) ===== */
html.prism-themeMode-sepia { filter: sepia(0.45) saturate(1.1) brightness(0.96); }
html.prism-themeMode-nord body { background-color: #2e3440 !important; color: #d8dee9 !important; }
html.prism-themeMode-nord .result__a, html.prism-themeMode-nord .result__title a { color: #88c0d0 !important; }
html.prism-themeMode-nord .result__url { color: #81a1c1 !important; }
html.prism-themeMode-nord .header-wrap, html.prism-themeMode-nord header { background: #3b4252 !important; }

/* ===== Custom colors ===== */
html.prism-on-customColors body { background-color: var(--prism-bgColor) !important; color: var(--prism-textColor) !important; }
html.prism-on-customColors .result__a, html.prism-on-customColors .result__title a, html.prism-on-customColors .result__a:link { color: var(--prism-linkColor) !important; }
html.prism-on-customColors a:visited, html.prism-on-customColors .result__a:visited { color: var(--prism-visitedColor) !important; }
html.prism-on-customColors .result__url, html.prism-on-customColors .result__extras, html.prism-on-customColors .result__snippet { color: var(--prism-urlColor) !important; }
html.prism-on-customColors .header-wrap, html.prism-on-customColors header, html.prism-on-customColors .header--search { background: var(--prism-headerColor) !important; }
html.prism-on-customColors .site-wrapper, html.prism-on-customColors .content-wrap { background: var(--prism-bgColor) !important; }

/* ===== Typography ===== */
html.prism-fontFamily-arial body { font-family: Arial, Helvetica, sans-serif !important; }
html.prism-fontFamily-georgia body { font-family: Georgia, serif !important; }
html.prism-fontFamily-verdana body { font-family: Verdana, Geneva, sans-serif !important; }
html.prism-fontFamily-tahoma body { font-family: Tahoma, sans-serif !important; }
html.prism-fontFamily-courier body { font-family: 'Courier New', monospace !important; }
html.prism-fontFamily-system body { font-family: -apple-system, 'Segoe UI', Roboto, sans-serif !important; }
html.prism-mod-duckduckgo .result, html.prism-mod-duckduckgo .result__body { font-size: calc(var(--prism-customFontScale, 100) * 1%) !important; }

/* ===== Layout ===== */
html.prism-on-compactResults .result { padding: 8px 12px !important; margin: 2px 0 !important; }
html.prism-on-compactResults .result__snippet { -webkit-line-clamp: 2 !important; }
html.prism-on-hideAds .result--ad, html.prism-on-hideAds .result.result--ad, html.prism-on-hideAds [data-testid='ad'] { display: none !important; }
html.prism-on-centerLogo .logo-wrap, html.prism-on-centerLogo .header__logo { display: flex !important; justify-content: center !important; margin: 0 auto !important; text-align: center !important; }
html.prism-on-stickyHeaderOff .header-wrap, html.prism-on-stickyHeaderOff header { position: static !important; }
html.prism-on-roundedCorners .result, html.prism-on-roundedCorners .search--adv, html.prism-on-roundedCorners .zci { border-radius: var(--prism-radius) !important; }
html.prism-on-roundedCorners .badge-circle, html.prism-on-roundedCorners .search__input { border-radius: calc(var(--prism-radius) * 0.6) !important; }

/* ===== Custom logo image ===== */
html.prism-mod-duckduckgo .logo-wrap img.logo-img,
html.prism-mod-duckduckgo .header__logo img,
html.prism-mod-duckduckgo .logo-homepage { transform: scale(calc(var(--prism-logoScale, 100) / 100)); transform-origin: left center; }
